'use client';

import { Avatar, Badge, Menu, useTheme, type ThemePreference } from '@yashwanthvarma74/react';
import Link from 'next/link';
import { usePathname, useRouter } from 'next/navigation';
import { useDemoAccounts, useDemoLogin, useLogout, useSession, useUnreadCount } from '@/lib/queries';
import styles from './AppHeader.module.css';

const LINKS = [
  { href: '/', label: 'Home' },
  { href: '/communities', label: 'Communities' },
  { href: '/search', label: 'Search' },
];

const THEMES: { value: ThemePreference; label: string }[] = [
  { value: 'system', label: 'Theme: match system' },
  { value: 'light', label: 'Theme: light' },
  { value: 'dark', label: 'Theme: dark' },
  { value: 'high-contrast', label: 'Theme: high contrast' },
];

export default function AppHeader() {
  const { data: user } = useSession();
  const pathname = usePathname();
  const router = useRouter();
  const unread = useUnreadCount(Boolean(user));
  const demoAccounts = useDemoAccounts();
  const demoLogin = useDemoLogin();
  const logout = useLogout();
  const { preference, setTheme } = useTheme();
  const count = unread.data ?? 0;

  const isCurrent = (href: string) => (href === '/' ? pathname === '/' : pathname.startsWith(href));

  return (
    <header className={styles.header}>
      <div className={styles.inner}>
        <Link href="/" className={styles.brand}>
          Pulse
        </Link>

        {user && (
          <nav aria-label="Main" className={styles.nav}>
            {LINKS.map((link) => (
              <Link key={link.href} href={link.href} className={styles.link} aria-current={isCurrent(link.href) ? 'page' : undefined}>
                {link.label}
              </Link>
            ))}
            <Link href="/notifications" className={styles.link} aria-current={isCurrent('/notifications') ? 'page' : undefined}>
              Notifications
              {count > 0 && (
                <Badge variant="accent" className={styles.count} aria-label={`${count} unread`}>
                  {count > 99 ? '99+' : count}
                </Badge>
              )}
            </Link>
          </nav>
        )}

        <Menu>
          <Menu.Trigger variant="ghost" size="sm" aria-label={user ? `Account menu for ${user.name}` : 'Display settings'}>
            {user ? (
              <>
                <Avatar name={user.name} size="sm" />
                <span className={styles.name}>{user.name}</span>
              </>
            ) : (
              'Display'
            )}
          </Menu.Trigger>
          <Menu.Content aria-label="Account" placement="bottom end">
            {user && (
              <Menu.Item id="profile" onAction={() => router.push(`/u/${user.handle}`)}>
                Your profile
              </Menu.Item>
            )}
            {user && (
              <Menu.Item id="settings" onAction={() => router.push('/settings')}>
                Settings and blocked people
              </Menu.Item>
            )}
            {user?.moderator && (
              <Menu.Item id="moderation" onAction={() => router.push('/moderation')}>
                Moderation queue
              </Menu.Item>
            )}
            {THEMES.map((theme) => (
              <Menu.Item key={theme.value} id={`theme-${theme.value}`} onAction={() => setTheme(theme.value)}>
                {theme.label}
                {preference === theme.value ? ' (current)' : ''}
              </Menu.Item>
            ))}
            {user && (demoAccounts.data?.length ?? 0) > 0 && <Menu.Separator />}
            {user &&
              demoAccounts.data?.map((account) => (
                <Menu.Item
                  key={account.handle}
                  id={`demo-${account.handle}`}
                  textValue={`Switch to ${account.name}`}
                  disabled={account.handle === user.handle}
                  onAction={() => demoLogin.mutate(account.handle, { onSuccess: () => router.push('/') })}
                >
                  Switch to {account.name}
                </Menu.Item>
              ))}
            {user && <Menu.Separator />}
            {user && (
              <Menu.Item id="logout" danger onAction={() => logout.mutate(undefined, { onSuccess: () => router.push('/') })}>
                Sign out
              </Menu.Item>
            )}
          </Menu.Content>
        </Menu>
      </div>
    </header>
  );
}
